    part_acc = stwo_qm31_add(part_acc, stwo_air_slice_fe7e9855cdfa1ccf_64(arena, args, row));
    part_acc = stwo_qm31_add(part_acc, stwo_air_slice_fe7e9855cdfa1ccf_80(arena, args, row));
