    part_acc = stwo_qm31_add(part_acc, stwo_air_slice_fe7e9855cdfa1ccf_160(arena, args, row));
    part_acc = stwo_qm31_add(part_acc, stwo_air_slice_fe7e9855cdfa1ccf_176(arena, args, row));
